"""Evidence bytes stay in private storage. Keys are generated by the server."""

import asyncio
import re
from pathlib import Path
from typing import Protocol

from app.core.config import Settings, get_settings
from app.core.errors import AppError

_KEY_RE = re.compile(r"^[a-f0-9]{32}\.[a-z0-9]{2,5}$")


class ObjectStorage(Protocol):
    async def save(self, key: str, data: bytes, mime: str) -> None: ...

    async def delete(self, key: str) -> None: ...


def validate_storage_key(key: str) -> str:
    if not _KEY_RE.fullmatch(key):
        raise AppError("invalid_storage_key", "Некорректный ключ файла.", 500)
    return key


class LocalStorage:
    def __init__(self, root: str) -> None:
        self._root = Path(root).resolve()

    def _path(self, key: str) -> Path:
        validate_storage_key(key)
        path = (self._root / key).resolve()
        if path.parent != self._root:
            raise AppError("invalid_storage_key", "Некорректный ключ файла.", 500)
        return path

    async def save(self, key: str, data: bytes, mime: str) -> None:
        del mime
        path = self._path(key)
        self._root.mkdir(parents=True, exist_ok=True)
        await asyncio.to_thread(_write_private, path, data)

    async def delete(self, key: str) -> None:
        path = self._path(key)
        if path.exists():
            await asyncio.to_thread(path.unlink)


class S3Storage:
    def __init__(self, settings: Settings) -> None:
        import boto3

        self._bucket = settings.s3_bucket
        self._client = boto3.client(
            "s3",
            endpoint_url=settings.s3_endpoint or None,
            aws_access_key_id=settings.s3_access_key,
            aws_secret_access_key=settings.s3_secret_key,
            region_name=settings.s3_region,
        )

    async def save(self, key: str, data: bytes, mime: str) -> None:
        validate_storage_key(key)
        await asyncio.to_thread(
            self._client.put_object,
            Bucket=self._bucket,
            Key=key,
            Body=data,
            ContentType=mime,
            ContentDisposition="attachment",
        )

    async def delete(self, key: str) -> None:
        validate_storage_key(key)
        await asyncio.to_thread(self._client.delete_object, Bucket=self._bucket, Key=key)


def get_storage() -> ObjectStorage:
    settings = get_settings()
    if settings.s3_bucket and settings.s3_access_key and settings.s3_secret_key:
        return S3Storage(settings)
    return LocalStorage(settings.storage_path)


def _write_private(path: Path, data: bytes) -> None:
    path.write_bytes(data)
    path.chmod(0o600)
